// Trezor wrapper that uses the global TrezorConnect library loaded from trezor-9.6.0.js
// This file is used to ensure that TrezorConnect is only loaded once and can be accessed globally
// This avoids webpack polyfill issues with Node.js core modules

let TrezorConnect = null

function getTrezorConnect() {
  if (TrezorConnect) {
    return TrezorConnect
  }

  if (typeof window !== 'undefined' && window.TrezorConnect) {
    TrezorConnect = window.TrezorConnect
    return TrezorConnect
  }

  throw new Error('TrezorConnect not available')
}

// Create a proxy that automatically loads TrezorConnect when needed
const TrezorConnectProxy = new Proxy(
  {},
  {
    get(target, prop) {
      return (...args) => {
        const trezor = getTrezorConnect()
        if (typeof trezor[prop] === 'function') {
          return trezor[prop](...args)
        }
        return trezor[prop]
      }
    }
  }
)

export default TrezorConnectProxy
